  "proverb": {
    "_id": "proverb-groundhog-day",
    "text": "Groundhog Day: if the groundhog sees its shadow, six more weeks of winter"
  },
  "statement": "In Punxsutawney, Punxsutawney Phil's published call (shadow = six more weeks of winter) matches whether 3 February to 16 March is colder than its 1991-2020 normal more often than chance.",
  "location": {
    "_id": "location-punxsutawney",
    "name": "Punxsutawney, Pennsylvania",
    "lat": 40.95,
    "lon": -78.98,
    "timeZone": "America/New_York",
    "coordinateSource": {
      "url": "https://en.wikipedia.org/w/api.php?action=query&prop=coordinates&titles=Punxsutawney,_Pennsylvania&format=json&formatversion=2",
      "retrievedAt": "2026-10-04",
      "note": "Wikipedia 40.94555556, -78.97527778, rounded to 2 dp"
