    "hourly": [
      "precipitation",
      "cloud_cover",
      "cloud_cover_low",
      "cloud_cover_mid",
      "cloud_cover_high",
      "wind_gusts_10m",
      "temperature_2m"
    ],
    "daily": [],
    "timezone": "GMT",
    "cellSelection": "land",
    "units": {
      "temperature": "celsius",
      "windSpeed": "kmh",
      "precipitation": "mm"
    },
    "timeformat": "iso8601",
    "startDate": "1950-01-01",
    "endDate": "2024-12-31",
    "points": [
      "location-punxsutawney"
    ],
    "reanalysisCaveat": "Gridded reanalysis (modelled, ~25 km cells), not station readings; it smooths local showers."
  },
  "timeRules": {
    "fetchTimeZone": "UTC (timezone=GMT); every timestamp is a UTC instant.",
    "localTimeZone": "America/New_York",
    "conversion": "UTC instants are converted to local wall-clock time in lab code with the IANA time zone database (Intl.DateTimeFormat).",
    "precipitationSemantics": "The precipitation value stamped at instant t is the sum over (t - 1 h, t] (Open-Meteo: \"Preceding hour sum\", 0.1 mm precision). The accumulation over a local interval [a, b) is the sum of values stamped at instants t with a < t <= b.",
