    "dailyMeanTemperature": "Daily mean temperature for local day D is the arithmetic mean of temperature_2m at every instant t with 00:00 D <= t < 00:00 D+1 (local).",
    "astronomy": "Sun and moon positions come from suncalc 2.1.0 at the location coordinates; no atmospheric refraction is applied beyond what suncalc does."
  },
  "unit": {
    "kind": "year",
    "definition": "Each year Y from 1950 to 2024 with a recorded call of either \"shadow\" or \"no shadow\"."
  },
  "predictor": {
    "variable": "Punxsutawney Phil's published call",
    "source": "The Punxsutawney Groundhog Club's published record of past predictions. The exact URL and retrieval date are stored with the data snapshot when retrieved. NOAA's Groundhog Day page is not used as the predictor source because it also reports outcomes.",
    "hours": {
      "from": "2 February Y",
      "to": "2 February Y",
      "interval": "the call made on 2 February Y"
    },
    "aggregation": "categorical",
    "comparator": "==",
    "threshold": "shadow",
    "conditions": [],
    "exclusion": "Years whose record is anything other than \"shadow\" or \"no shadow\" are excluded and listed."
  },
  "outcome": {
    "variable": "temperature_2m",
    "point": "location-punxsutawney",
    "hours": {
      "from": "3 February Y",
      "to": "16 March Y",
      "interval": "local days, inclusive (42 days; 43 in leap years)"
    },
    "aggregation": "W(Y) = mean of the daily mean temperatures over the window",
    "comparator": "<",
    "threshold": "N = mean of W(Y) over Y = 1991..2020 (the 30 window means from the same ERA5 series)",
    "units": "degrees C",
    "conditions": [],
    "hit": "A hit is (call = shadow AND W(Y) < N) OR (call = no shadow AND W(Y) >= N)."
  },
  "comparison": "Hit rate vs 50%",
  "effect": {
    "metric": "hit rate",
    "definition": "100 * hits / scored years",
    "units": "percent",
    "nullValue": 50
  },
  "test": {
    "name": "exact binomial test",
    "sidedness": "two-sided",
    "nullProbability": 0.5,
    "implementation": "As R binom.test(hits, n, p = 0.5): sum of binomial probabilities no greater than that of the observed count, with relative tolerance 1e-7."
  },
  "smallestEffect": {
    "value": 60,
    "units": "percent hit rate"
  },
  "bootstrap": {
    "method": "bootstrap of years",
    "resamples": 10000,
    "blockLength": 1,
    "blockUnit": "year",
    "procedure": "Resample scored years with replacement and recompute the hit rate. The normal N is held fixed. 7-day blocks do not apply to yearly units.",
    "ci": "95% percentile interval: the 2.5th and 97.5th percentiles of the bootstrap effects, linear interpolation between order statistics (R quantile type 7).",
    "prng": {
      "algorithm": "mulberry32",
      "seed": 20261004,
      "note": "A fresh generator seeded with this value for each hypothesis."
    }
  },
  "verdictRules": {
    "order": "Evaluated top to bottom; the first rule that matches decides.",
    "predictedDirection": "effect > 50",
    "smallestEffectOfInterest": "60 percent hit rate",
    "rules": [
      {
        "verdict": "Supported",
        "when": "adjusted p < 0.05 AND effect > 50 AND effect >= 60"
      },
      {
        "verdict": "Contradicted",
        "when": "adjusted p < 0.05 AND effect < 50"
      },
      {
        "verdict": "Not supported",
        "when": "(adjusted p < 0.05 AND effect > 50 AND effect < 60) OR (CI high < 60)"
      },
      {
        "verdict": "Inconclusive",
        "when": "otherwise"
      }
    ],
    "departureFromSpec": "The spec stamps any significant effect in the predicted direction as Supported. With ~27,000 daily units almost any difference is significant, so Supported here also requires the point estimate to reach the smallest effect of interest; significant-but-smaller effects are Not supported. Decided by the project owner on 2026-10-04, before any data was fetched."
  }
}

